329	fn parse_name<'s>(s: &mut Scanner<'s>) -> Result<&'s str, EcoString> {
330	    s.eat_if('/');
331	
332	    let name = s.eat_until(':');
333	    if name.is_empty() {
334	        Err("package specification is missing name")?;
335	    } else if !is_ident(name) {
